import { mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { sniffImage } from "./images";

export function localImagePath(root: string, key: string) {
  // Object keys are generated by the app, never OS paths supplied by a browser.
  if (!/^(?:radars|lineups)\/[a-zA-Z0-9_./-]+$/.test(key) || key.split("/").some((s) => !s || s === "." || s === "..")) {
    throw new Error("Invalid image object key");
  }
  const base = path.resolve(root);
  const target = path.resolve(base, ...key.split("/"));
  if (!target.startsWith(base + path.sep)) throw new Error("Image path escapes storage");
  return target;
}

export async function readLocalImage(root: string, key: string) {
  try {
    const bytes = await readFile(localImagePath(root, key));
    const image = sniffImage(bytes);
    if (!image.ok) throw new Error("Invalid stored image");
    return { body: new Blob([bytes]).stream(), contentType: image.type, contentLength: bytes.length };
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
}

export async function writeLocalImage(root: string, key: string, bytes: Uint8Array) {
  if (!sniffImage(bytes).ok) throw new Error("Invalid image upload");
  const target = localImagePath(root, key);
  await mkdir(path.dirname(target), { recursive: true });
  await writeFile(target, bytes);
}

export async function deleteLocalImage(root: string, key: string) {
  try { await unlink(localImagePath(root, key)); }
  catch (error) { if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error; }
}
